using System.Net;
using Campfire.IntegrationTests.Support;
using Campfire.Web.Hosting;
using Campfire.Web.Paths;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.TestHost;
using Microsoft.Extensions.Logging;

namespace Campfire.IntegrationTests.Slice;

/// <summary>Public health and imported avatar contracts from the Rails verification fixture.</summary>
public sealed class HarnessConformanceTests
{
    // Generated by User.signed_id_verifier in the pinned Rails 8.2 image, using a public synthetic secret.
    private const string Secret = "official-harness-avatar-golden-secret-v1-0123456789abcdef0123456789abcdef";
    private const string Avatar = "eyJfcmFpbHMiOnsiZGF0YSI6MTI3MzI2MTQxLCJwdXIiOiJ1c2VyL2F2YXRhciJ9fQ--a07d8cce97322e6da52f36f12356c2e5abdd67b0429b39659183627b6d1f1353";
    private const string Health = "<!DOCTYPE html><html><body style=\"background-color: green\"></body></html>";

    [Theory]
    [InlineData( "GET" )]
    [InlineData( "HEAD" )]
    public async Task Health_ignores_a_valid_cookie_and_unavailable_session_tables( string method )
    {
        await using var factory = new SliceAppFactory( );
        using var client = factory.Client( );
        client.SignInAs( factory, SliceAppFactory.Id( "david" ) );
        factory.Execute( "ALTER TABLE sessions RENAME TO unavailable_sessions" );

        using var request = new HttpRequestMessage( new HttpMethod( method ), Routes.RailsHealthCheck );
        var response = await client.SendAsync( request );

        Assert.Equal( HttpStatusCode.OK, response.Status );
        Assert.Equal( "text/html; charset=utf-8", response.ContentType );
        Assert.Equal( method == "HEAD" ? "" : Health, response.Body );
        Assert.Null( response.Raw( "Set-Cookie" ) );
    }

    [Fact]
    public async Task Health_answers_http_even_when_the_public_front_requires_https( )
    {
        await using var factory = new HealthTlsFactory( );
        using var client = factory.Client( );

        using var healthRequest = new HttpRequestMessage( HttpMethod.Get, Routes.RailsHealthCheck );
        healthRequest.Headers.Host = "chat.example.test";
        var health = await client.SendAsync( healthRequest );
        Assert.Equal( HttpStatusCode.OK, health.Status );
        Assert.Equal( Health, health.Body );
        using var protectedRequest = new HttpRequestMessage( HttpMethod.Get, Routes.NewSession );
        protectedRequest.Headers.Host = "chat.example.test";
        var protectedPage = await client.SendAsync( protectedRequest );
        Assert.Equal( HttpStatusCode.MovedPermanently, protectedPage.Status );
        Assert.StartsWith( "https://", protectedPage.Location, StringComparison.Ordinal );
    }

    [Theory]
    [InlineData( Secret, true )]
    [InlineData( "different synthetic secret", false )]
    [InlineData( "", false )]
    [InlineData( " ", false )]
    public async Task Imported_avatar_links_require_the_original_nonblank_secret( string secret, bool accepted )
    {
        await using var factory = new AvatarFactory( secret );
        using var client = factory.Client( );
        client.SignInAs( factory, SliceAppFactory.Id( "david" ) );
        var imported = await client.GetAsync( $"/users/{Avatar}/avatar", "image/*" );

        Assert.Equal( accepted ? HttpStatusCode.OK : HttpStatusCode.NotFound, imported.Status );
        if ( accepted )
        {
            var native = factory.App.SignedIds.Generate( "User", SliceAppFactory.Id( "david" ), "avatar" );
            var current = await client.GetAsync( $"/users/{native}/avatar", "image/*" );
            Assert.Equal( HttpStatusCode.OK, current.Status );
            Assert.Equal( current.Body, imported.Body );
            Assert.StartsWith( "image/", imported.ContentType, StringComparison.Ordinal );
        }
    }

    private sealed class AvatarFactory( string secret ) : SliceAppFactory
    {
        protected override void ConfigureWebHost( IWebHostBuilder builder )
        {
            base.ConfigureWebHost( builder );
            builder.UseSetting( "SECRET_KEY_BASE", secret );
        }
    }

    private sealed class HealthTlsFactory : SliceAppFactory
    {
        protected override void ConfigureWebHost( IWebHostBuilder builder )
        {
            base.ConfigureWebHost( builder );
            builder.UseSetting( "DISABLE_SSL", "" );
            builder.ConfigureTestServices( services =>
            {
                var front = new FrontServerOptions
                {
                    Enabled = true,
                    TargetPort = 0,
                    Domains = ["chat.example.test"],
                    LogRequests = false
                };
                services.AddSingleton( front );
                services.AddSingleton( provider => new AutomaticCertificates( front,
                    provider.GetRequiredService<ILogger<AutomaticCertificates>>( ), TimeProvider.System ) );
            } );
        }
    }
}
